export function buildZigBee(host,{antenna=host.options.antenna??false,antennaAngleDeg=host.options.antennaAngleDeg??0}={}){if(typeof antenna!=='boolean')throw new TypeError('antenna must be true or false');const parts=addCadParts(host,data,{shell:materials.plastic(0x535653,{roughness:.86})}),pcb=board(host),output=sma(host),input=grove(host),fixings=[];for(const[x,y]of[[0,-20],[-8.2,27.4],[8.2,27.4]]){fixings.push(screw(host.body,[x,y,-3.97],'back',1.35));mesh(host.body,new THREE.CylinderGeometry(.6,.6,1.8,24).rotateX(Math.PI/2),materials.metal(0xa4a799),[x,y,-2.7],'ZigBee fixed concealed shell screw shank');}
 const film=materials.plastic(0xd8d9d6,{roughness:.87}),front=slab(host.body,...spec.labels.front.size,.08,.5,spec.labels.front.position,film,[],.005),back=slab(host.body,...spec.labels.back.size,.08,.5,spec.labels.back.position,film,[],.005);front.name='ZigBee physical front adhesive film seated on native closed label recess';back.name='ZigBee physical back adhesive film seated on native closed label recess';front.userData={role:'physical-label-substrate',face:'front'};back.userData={role:'physical-label-substrate',face:'back'};host.zigbeeAssembly={parts,pcb,output,input,fixings,labels:{front,back}};host.unitStickers=addStickers(host);if(antenna)output.port.attach(new Antenna({angleDeg:antennaAngleDeg,artwork:host.options.artwork}));}
